-- GENERATED by `wfj generate` from data/quest/quest-0093.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [93034] = { "La ⟦Valley of Bones=Valle delle Ossa⟧", "Migliora la tua reputazione presso i Gelkis e trova Nerlokh vicino alla ⟦Valley of Bones=Valle delle Ossa⟧, molto a est del ⟦Gelkis Village=Villaggio dei Gelkis⟧.", "Mentre eri via, uno dei nostri esploratori è tornato al villaggio con notizie che hanno confermato i miei timori.\n\nI Magram stanno tramando qualcosa, {name}. E non è niente di buono.\n\nLa ⟦Valley of Bones=Valle delle Ossa⟧, molto a est, è una terra maledetta in cui pochi centauri hanno osato entrare, e ancora meno ne sono tornati. Il nostro nemico vi ha trovato qualcosa, qualcosa di malvagio, e dobbiamo scoprire di cosa si tratta.\n\nCerca l'esploratore Nerlokh all'ingresso meridionale, ma forse dovrai dimostrare ancora il tuo valore ai Gelkis.", nil, nil, 0x1c23f49e, 0xc34a0910, 0xad8eaac4, nil, nil, "...mm" },
  [93035] = { "Devastare i devastatori", "Mantieni la tua reputazione presso i Gelkis e uccidi $N1 Undead Ravager, poi torna da Nerlokh all'ingresso meridionale della ⟦Valley of Bones=Valle delle Ossa⟧.", "Non serve guardare lontano per vedere i non morti che si trascinano davanti a noi, ma hai notato qualcosa di strano in loro?\n\nCamminano su due gambe, non su quattro! Questi scheletri non sono nemmeno i nostri congiunti caduti. I Magram devono profanare i corpi di chi è morto molto prima che ⟦Desolace=Desolanda⟧ fosse il nostro dominio. Non riesco a immaginare come abbiano giustificato il voltare le spalle a Madre Theradras e il dissacrare cadaveri che riposano qui da secoli.\n\nDai pace ai non morti, {name}.", nil, nil, 0x153e1e0b, 0x5480b72b, 0x3fc928fd, nil, nil, "...mm" },
  [93036] = { "Infiltrarsi nel culto", "Parla con Sania Silverstream a Shen'dar Village.", "Forse lo sai, forse no, ma Sania Silverstream, laggiù, è una \"missionaria\" degli Al'Aketh. A loro piace fingersi un normale ordine religioso e mandano in giro emissari inoffensivi a reclutare. Finora abbiamo tollerato Sania per evitare uno scontro diretto con il culto, ma è chiaro che l'illusione della pace non durerà ancora a lungo.\n\nSei <nuovo/nuova> di qui e quasi nessuno ti conosce, quindi vorrei vedere se riesci a usare Sania per avvicinarti al culto e scoprire che piani hanno per il villaggio.", nil, "Salute, <figlio/figlia>, il mio nome è Sania Silverstream e sono una sacerdotessa novizia dell'Ordine degli Al'Aketh. Vuoi saperne di più sul nostro sovrano, il Signore del Vento Al'Akir?\n\nAlla tavola del Signore del Vento c'è sempre posto per i giusti e per i pentiti.", 0xbb1fd4b2, 0x82bd3020, 0x59a588f5, nil, 0x23ca2220, "...m." },
  [93037] = { "Smascherare gli esiliati", "Mantieni la tua reputazione presso i Gelkis e porta $N1 Necromantic Garb a Nerlokh, all'ingresso della ⟦Valley of Bones=Valle delle Ossa⟧.", "Mentre aspettavo il tuo arrivo, ho guardato un po' più in là, tra gli archi, e ho notato qualcosa che ho bisogno che tu mi confermi.\n\nNon sopporto di dirlo ad alta voce. Non finché i miei sospetti non saranno provati.\n\n{name}, mentre prendi confidenza con la valle, uccidi alcuni dei negromanti che sembrano più deboli degli altri. Strappa loro le vesti rituali, con cura, e portamele. Devo sapere se la mia mente e la mia vista sono lucide.", nil, nil, 0x7c82b69a, 0xffce3927, 0x80ee307a, nil, nil, "...mm" },
  [93041] = { "Affrontare la verità", "Mantieni la tua reputazione presso i Gelkis e porta un Accursed Skull e la Gelkis Necromantic Garb a Uthek la Saggia al ⟦Gelkis Village=Villaggio dei Gelkis⟧.", "Questa scoperta è devastante per il nostro clan, ma è nel nostro interesse che la conosca solo chi deve saperla. Uthek è una di queste persone: deve essere al corrente di ciò che succede qui. Credo che saprà come procedere.\n\nPorta questa e mostragliela. Per sicurezza dovremmo portarle anche una prova della negromanzia stessa. Trova un teschio che sembri maledetto da poco. Sospetto che li ammassino tra le fauci di uno degli scheletri dei giganti.", nil, nil, 0x8463c2a2, 0x5ff29d36, 0x49b8d0dc, nil, nil, "...mm" },
  [93044] = { "Un grido purificatore", "Mantieni la tua reputazione presso i Gelkis e porta le Tears of Theradras a Uthek la Saggia al ⟦Gelkis Village=Villaggio dei Gelkis⟧.", "Quando tornerai da Nerlokh nella ⟦Valley of Bones=Valle delle Ossa⟧, non sarà a mani vuote.\n\nEntra nella grotta nel cuore del nostro villaggio e cerca Mulara. Chiedile le lacrime di Theradras a nome mio. Le nostre scorte sono scarse, ma sono la nostra migliore speranza contro l'immonda negromanzia dei Magram!\n\nIo preparerò un rituale. Creeremo un'arma per spezzare i loro incantesimi.", nil, nil, 0x0d21377b, 0xf97c47c3, 0x548749f1, nil, nil, "...mm" },
  [93045] = { "Metti alla prova la tua teoria", "Mantieni la tua reputazione presso i Gelkis e dissolvi la maledizione negromantica che grava sull'Accursed Skull. Quando ci sarai riuscit<o/a>, torna a fare rapporto a Nerlokh vicino alla ⟦Valley of Bones=Valle delle Ossa⟧.", "Ho messo il teschio che mi hai dato accanto a varie ossa che ho trovato mentre aspettavo il tuo ritorno. Subito ho visto una luce malsana diffondersi dal teschio e fare sue quelle vecchie ossa. Ora capisco perché il richiamo della negromanzia sia così difficile da resistere.\n\nTi ricordi di questo cristallo? È draenetista. Ne conosco poco le potenzialità, ma credo che possa incanalare il potere di Theradras. Con esso, forse potrai dissolvere la maledizione.\n\nIl luogo del rituale si trova vicino allo stagno, appena a est del villaggio.", nil, nil, 0xdd0047fc, 0x79d5c999, 0x89f01149, nil, nil, "...mm" },
  [93058] = { "Salvare i nostri", "Mantieni la tua reputazione presso i Gelkis e libera $N1 Gelkis Captive nella ⟦Valley of Bones=Valle delle Ossa⟧. Quando hai finito, torna da Nerlokh vicino all'ingresso.", "C'è stata una breve battaglia tra alcuni negromanti, appena dietro la collina, e ne ho approfittato per dare un'occhiata più da vicino all'interno.\n\n{name}, non tutte le nostre perdite recenti erano disertori. Ci sono dei Gelkis tenuti prigionieri più avanti nella valle! Non ho potuto indagare sulla loro situazione perché un enorme bruto dei Magram ha iniziato a caricare verso di me. Mi ritengo fortunato che abbia perso interesse in fretta.\n\nDevi tornare nella ⟦Valley of Bones=Valle delle Ossa⟧ e liberarli. I Gelkis restano uniti.", nil, nil, 0x76503b38, 0x148d8d61, 0x52532c02, nil, nil, "...mm" },
  [93062] = { "Seppellire le ossa", "Mantieni la tua reputazione presso i Gelkis e dissolvi le maledizioni di $N1 evocazioni fallite in tutta la ⟦Valley of Bones=Valle delle Ossa⟧.", "A proposito di questo tuo bastone. Lo riconosco, è uno di quelli di Uthek, e hai detto che è stato costruito con le lacrime di Theradras, potenziato con un ⟦Draenethyst Crystal=Cristallo di Draenetista⟧, e che può dissolvere la magia oscura?\n\nHo notato che ci sono scheletri bloccati appena sotto il terreno roccioso, più avanti nella valle. Credo che siano evocazioni fallite dei negromanti esiliati, condannate forse per sempre a un'esistenza soffocata nella terra.\n\nRiportarli al riposo gioverebbe alla nostra causa, e ai loro spiriti.", nil, nil, 0x25960f2c, 0x00d4e816, 0x21e3a666, nil, nil, "...mm" },
  [93065] = { "Prepararsi alla battaglia", "Parla con Valennia Stormfist nei Gustberry Lowlands.", "I Pacificatori si stanno mobilitando e ci stiamo tutti preparando a partire. Fai tutti i preparativi che ti servono e raggiungici sulla strada orientale che porta a nord, fuori dal paese. Faremo un ultimo controllo con tutti prima di metterci in marcia.", nil, "Siamo pronti più che mai.", 0x5db1f556, 0xd94373fd, 0x8619e90a, nil, 0xda1d39ff, "...m." },
  [93066] = { "Il rifugio dei ⟦Bristleback=Mantotergo⟧", "Mantieni la tua reputazione presso i Magram e uccidi i verrospini al rifugio dei ⟦Bristleback=Mantotergo⟧. Poi fai rapporto a Hagiak al Magram Front, dall'altra parte della ⟦Valley of Bones=Valle delle Ossa⟧, a ⟦Desolace=Desolanda⟧.", "Dall'altra parte della valle abbiamo stabilito un piccolo avamposto per prepararci a marciare nella foresta vicina. Prima di andare dritt<o/a> laggiù, voglio che ti occupi di una recente incursione dei ⟦Bristleback=Mantotergo⟧ lungo la strada. Sembra che siano arrivati più o meno quando siamo arrivati noi, ma sono riusciti a impadronirsi di un manufatto del tempio vicino che ci ha tenuti a distanza.\n\nIl compito è semplice. Cerca le spine e i maiali. Uccidine un bel po', senza distinzione. Poi fai rapporto a Hagiak all'accampamento di cui ti ho parlato.", nil, nil, 0x6802c038, 0x895f28cd, 0x20e4bcb9, nil, nil, "...mm" },
  [93072] = { "Soluzioni a lungo termine", "Mantieni la tua reputazione presso i Magram e uccidi $N1 Outcast Scout, $N2 Outcast Marauder e $N3 Outcast Necromancer, poi torna da Hagiak al Magram Front.", "Qui fuori c'è un secondo villaggio di centauri, a sud-ovest. Quello appartiene ai Gelkis. Ti aspetti che ti mandi laggiù solo per versare un po' di sangue, giusto? Bene. Sarà meglio che sia il tuo primo pensiero, altrimenti metterei in dubbio la tua fedeltà ai Magram!\n\nCosa aspetti? Va'! Uccidi!", nil, nil, 0xaf937461, 0x1208c910, 0xd1a41853, nil, nil, "...mm" },
  [93089] = { "Ciò che verrà", "Parla con Elaadrin Evengale quando sei pront<o/a> a lasciare Zephras Isle.", "Ti prego, porta i miei ringraziamenti a Elaadrin per tutto ciò che l'High Order e i tuoi nuovi amici di questo \"Kirin Tor\" hanno fatto per Zephras Isle. So che l'High Order intende lasciare l'isola, e il vostro ordine ha la mia benedizione e i miei auguri per questa spedizione.\n\nPosso solo sperare che qualunque soluzione arcana trovi l'High Order possa davvero darci la stabilità che ci è mancata in questi anni. Se intendi andare con loro... be', questa missione ne uscirà ancora più forte.\n\nChe i venti siano con te, {name}.", nil, "Mi rallegra sapere che abbiamo la benedizione dell'alto anziano Shadowsong per la nostra spedizione. Ora che il culto è stato sconfitto e i preparativi sono fatti, credo che sia finalmente giunto il momento.\n\nAnsirem ha lavorato con impegno per aiutarci ad avviare un trasporto stabile di skycutter tra la città di Dalaran e Zephras Isle. Abbiamo fatto tutte le prove possibili, ed è giunto il momento che la nostra avanguardia parta.", 0x50a257df, 0xb2d66ffb, 0xa384a68c, nil, 0xd86a7736, "...m." },
  [93090] = { "Ciò che verrà", "Parla con Ayessa Dawnsinger quando sei pront<o/a> a lasciare Zephras Isle.", "Ti prego, porta i miei ringraziamenti ad Ayessa per tutto ciò che i Windshaper e i tuoi nuovi amici di questo \"Earthen Ring\" hanno fatto per Zephras Isle. So che c'è il piano di portare via dall'isola gli sciamani dei Windshaper, e il vostro ordine ha la mia benedizione e i miei auguri per questa spedizione.\n\nPosso solo sperare che qualunque soluzione trovino i Windshaper possa davvero darci la stabilità che ci è mancata in questi anni.\n\nChe i venti siano con te, {name}.", nil, "Sono lieta di sapere che abbiamo la benedizione dell'alto anziano Shadowsong per la nostra spedizione. Ora che il culto è stato sconfitto e i preparativi sono fatti, credo che sia finalmente giunto il momento.\n\nMuln ha lavorato con impegno per aiutarci ad avviare un trasporto stabile di skycutter tra Zephras Isle e un luogo chiamato Mulgore, dove ha sede l'Earthen Ring. Abbiamo fatto viaggi di prova e alcuni dei nostri aspettano già dall'altra parte.", 0x50a257df, 0x42ef0bb4, 0xfa29d4a6, nil, 0xeaba7e66, "...m." },
  [93122] = { "Dare un'occhiata in giro", "Mantieni la tua reputazione presso i Gelkis e indaga sui punti d'interesse dei centauri a Shen'dralas. Poi torna da Nerlokh, all'ingresso della ⟦Valley of Bones=Valle delle Ossa⟧, con ciò che hai scoperto.", "Abbiamo tutti sottovalutato la forza e la presenza del clan dei Magram in questa zona, ma potrebbe rivelarsi un vantaggio.\n\nCon tanti dei loro distratti, e con il loro rifiuto di accogliere gli esiliati degli altri clan, chi è rimasto a difendere il villaggio? E il loro Khan?\n\nHo bisogno che tu entri nella valle, più a fondo di quanto tu abbia mai fatto, e che ti guardi intorno. Se i Magram sono così ben fortificati qui come sembra, potrebbero aver lasciato scoperto il loro villaggio...", nil, nil, 0x9009cbea, 0x26ae294d, 0x1c056f62, nil, nil, "...mm" },
  [93125] = { "Tornare a casa", "Mantieni la tua reputazione presso i Gelkis e scorta Rokren fuori dall'Outcast Hideaway. Poi racconta a Nerlokh, vicino alla ⟦Valley of Bones=Valle delle Ossa⟧, cos'è successo.", "Tu! Ti ho vist<o/a> là fuori combattere gli esiliati. Non so da dove vieni, ma ho bisogno del tuo aiuto.\n\nSono stato attirato qui dai miei fratelli Gelkis con la promessa che sarei stato al sicuro. Sapevo che la guerra a ⟦Desolace=Desolanda⟧ ci stava sfuggendo di mano, ma non avrei mai immaginato che la mia stessa gente si sarebbe rivolta alla negromanzia in un contorto tentativo di passare al clan dei Magram. Quando mi sono opposto, hanno minacciato di uccidermi se avessi mai messo zoccolo fuori da questa tenda!\n\nTi prego, aiutami.", nil, nil, 0xf193b151, 0x86ad2352, 0x15267230, nil, nil, "...mm" },
  [93128] = { nil, "Mantieni la tua reputazione presso i Gelkis e uccidi Khan Jhen al Magram Village. Quando ci sarai riuscit<o/a>, fai rapporto a Uthek la Saggia al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧.", "Per quanto vorrei che fossero Uthek o Khan Shaka a dare l'ordine, temo che la nostra occasione sia breve. Troppo breve per consultare chi sta al ⟦Gelkis Village=Villaggio dei Gelkis⟧.\n\nCredo che, con ciò che sta accadendo qui nella ⟦Valley of Bones=Valle delle Ossa⟧, i Magram abbiano lasciato Khan Jehn con difese minime. Se mai c'è stato un momento per attaccare il Khan di un altro clan, è adesso.\n\nMa, {name}, con un Khan non si scherza, e meno che mai con Jehn. Se hai il coraggio di fare la tua mossa, devi essere rapid<o/a>, ma non sottovalutarlo.", nil, nil, 0x67d27eda, 0xe9180567, 0xe9fc8e6f, nil, nil, "e..mm" },
  [93129] = { "La minaccia della fame", "Mantieni la tua reputazione presso i Magram e riporta $N1 Stolen Supplies a Hagiak al Magram Front.", "Visto che sembri fin troppo ansios<o/a> di aiutare il nostro clan, sono sicuro che saresti dispost<o/a> a recuperare qualche provvista mentre sei all'Outcast Hideaway.\n\nAbbattere i nostri nemici dovrebbe bastare come motivazione per un Magram, ma non vedo perché non potremmo trarne anche un profitto.\n\nQuando avremo sistemato gli esiliati, potremo assicurare questo posto ai Magram e radunare un esercito per mettere in ginocchio gli altri clan!", nil, nil, 0x73784842, 0xa76555fc, 0xd084fd3d, nil, nil, "...mm" },
  [93159] = { "Lo strano eremita", "Parla con lo Strange Hermit nella Shadowgale Forest e scopri di più su di lui.", "Ehm, uhm... c-ciao, cioè, volevo dire, salve! Anzi, saluti! Scusa... è, uhm, passato così tanto tempo dall'ultima volta che ho parlato davvero con un'altra persona. Temo di essere un po' arrugginito.\n\n<La strana figura incappucciata si agita a disagio davanti a te.>\n\nAllora, ehm, uhm... come va la tua giornata?", nil, "...questo è più o meno tutto quello che ho da dire in proposito. Ero... uhm... da qualche altra parte prima di essere qui. Ora sono qui e ho i miei amici e le mie cose. C-cose che ho costruito, intendo. È più o meno tutto ciò di cui ho bisogno. Credo che sia tutto ciò di cui ho bisogno, comunque.\n\nDevo dire, però, che è bello parlare con qualcuno che risponde. Gli spiriti della foresta ci provano, ma finiscono sempre per cantarmi addosso. È bello a modo suo, ma non è proprio una conversazione s-stimolante.", 0xc281d56b, 0x91510117, 0x813fe37d, nil, 0xf694abb5, "...m." },
  [93160] = { "I doni della foresta", "Raccogli $N1 Shadowgale Acorn nella Shadowgale Forest.", "Mi fa davvero piacere che tu sia passat<o/a> a parlare con me! S-se vuoi darmi una mano, mi servirebbe un po' d'aiuto a raccogliere le ghiande dal suolo della foresta. Ho già raccolto quasi tutte quelle qui vicino, ma nella foresta ci sono davvero tanti di quei cosi a metà tra raptor e uccelli. Là fuori è pericoloso e preferirei non diventare il pranzo di un uccello gigante!\n\nQuindi, se vuoi, magari potresti raccoglierle tu per me? Se lo fai, preparerò qualcosa di buono per tutti e due!", "Mmm, credo che ti piacerà quello che riesco a cucinare con queste ghiande!", "Grazie, <straniero/straniera>! Vedrai che sono deliziose, una volta arrostite!\n\nScusami, non ci metterò molto a prepararle.", 0x4aa75777, 0x076dacd0, 0xb98c76cc, 0xd9fab18b, 0xc1c8b911, "....." },
  [93165] = { "La pietà cade nel vuoto", "Raccogli $N1 Al'Aketh Cultist's Ear dai cultisti Al'Aketh nella Shadowgale Forest, allo Shrine of Akir o nei Gustberry Lowlands.", "Gli Al'Aketh hanno portato una grande tragedia sulla nostra enclave, e il sangue va ripagato con il sangue.\n\nHo un'offerta per te, <straniero/straniera>. Se ti trovi a scontrarti con questi cultisti maledetti, portami le orecchie di quelli che uccidi. Ti ricompenserò per ognuna che mi porterai, con denaro e, col tempo, con l'accesso ai segreti dei Nightclaw, se dimostrerai di essere un vero amico.", "Non avrò pace finché le mie zanne non avranno squarciato la gola di ogni singolo cultista di quest'isola.", "Ottimo lavoro. Eliminare il culto non può che portare del bene. Spero che questo faccia capire che con i Nightclaw non si scherza e che i nostri rancori sono profondi.\n\nCredo che ti aspetti un bel po' di lavoro, a combattere il culto. Se raccogli altre orecchie, portale qui.", 0x67167132, 0x29ccfeb1, 0xf3604d96, 0x3dfb4bed, 0x83d85581, "....." },
  [93172] = { "Liberare gli Hollow", "Distruggi 10 Wind Hollow nella Shadowgale Forest.", "Quasi tutti gli elfi di quest'isola pensano che questi boschi siano infestati, e non hanno torto.\n\nAlle antiche rovine a nord-est si raduna uno strano tipo di spiriti simili a fantasmi. Certe notti si possono quasi sentire \"cantare\". Non somiglia a nessun canto che abbia mai sentito, ma è di sicuro un canto ed è... così triste.\n\nNon so perché, ma credo che lì, a un certo punto, sia successo qualcosa di terribile, e che gli spiriti ci siano rimasti intrappolati in qualche modo. Se te la senti, forse puoi aiutarli a liberarsi?", nil, "Grazie, <straniero/straniera>.", 0x0e18dc30, 0x1267d2ac, 0xe5c300d2, nil, 0x66dd9c71, "...m." },
  [93173] = { "(UNUSED) Il Rusty Gadget", "Riporta il Rusty Gadget allo Strange Hermit nella Shadowgale Forest.", "<Mentre le correnti vorticose che tengono insieme il Wind Hollow cominciano a dissolversi, un piccolo congegno di metallo cade a terra ai tuoi piedi. Sembra una specie di aggeggio meccanico. Lo Strange Hermit ha detto che gli mancava ancora dell'attrezzatura. Potrebbe interessargli.>", nil, nil, 0xd8c783cf, 0x3216fc08, 0x02764b22, nil, nil, "...mm" },
  [93176] = { "I miei piccoli amici", "Usa gli oggetti contenuti nell'Entomology Starter Kit per trovare e catturare un Arbor Tarantula, un Hay Weevil Specimen e un Flesh Picker.", "Ammiri il mio piccolo serraglio, eh? È l'opera della mia non-vita. Ho passato ore e ore a studiarli: la loro anatomia, la loro dieta, perfino i loro rituali sociali.\n\nVuoi unirti a me in questo passatempo? Ecco, prendi questo pacco. Gli appunti e il materiale che contiene dovrebbero bastarti per cominciare. Se lo perdi, dovrai comprarne un altro da me per una piccola somma.", nil, nil, 0xd9137740, 0x98c50d57, 0xc04ef699, nil, nil, "...mm" },
  [93188] = { "Ritorno da Orgrul", "Mantieni la tua reputazione presso i Magram e torna a fare rapporto a Orgrul, vicino all'ingresso settentrionale della ⟦Valley of Bones=Valle delle Ossa⟧.", "Hai fatto abbastanza in prima linea. Possiamo cavarcela da soli.\n\nDi' a Orgrul che hai fatto la tua parte. Il Magram Front ora è più forte, e abbiamo messo gli occhi sull'accampamento degli esiliati come nostro prossimo insediamento, quando un'altra schiera di combattenti si unirà alla mischia.\n\nAllora? Muoviti!", nil, nil, 0x14b1f8e5, 0x30764b3d, 0x99bb3d87, nil, nil, "...mm" },
  [93196] = { nil, "Mantieni la tua reputazione presso i Magram e compi un rituale negromantico per resuscitare Khan Jehn. Il luogo del rituale si trova in una tenda presso il lago centrale del Magram Village.", "Il capo del nostro clan, Khan Jehn, è stato ucciso da una banda di stranieri molto simili a te. Agivano per conto del clan dei Gelkis.\n\nPuoi smettere di fingerti sorpres<o/a>. Un assalto al Magram Village mentre la nostra attenzione era altrove è una strategia di guerra prevedibile, soprattutto per i Gelkis.\n\nSai perché non mostro né rabbia né rimorso, <straniero/straniera>?\n\n<Orgrul ti porge un'arma familiare, intrisa di un potere ancora più grande dell'ultima volta che l'hai impugnata.>\n\nEcco perché.", nil, nil, 0x67d27eda, 0x571f4b9c, 0xc11d031e, nil, nil, "e..mm" },
  [93224] = { "Totem intagliati dei centauri", "Ottieni $N1 Carved Centaur Totem uccidendo centauri di qualsiasi clan in tutta ⟦Desolace=Desolanda⟧, poi portali al capitano Pentigast al ⟦Nijel's Point=Presidio di Nijel⟧.", "Probabilmente non ti sorprende che entrambi i clan di centauri siano restii ad accettare aiuto da chiunque non faccia parte del loro clan. Questo vale soprattutto per gente come te e me... sai, i non centauri.\n\nUna cosa che abbiamo tutti in comune è la consapevolezza che il denaro è potere, e abbiamo scoperto che i centauri del posto commerciano con legno intagliato. Se mi porti qualche esempio dei loro disegni, posso fare un ordine urgente di incisioni simili. Forse riusciremo a comprarci un vantaggio.", nil, nil, 0x9d52128a, 0xa608090a, 0x7f0dbe84, nil, nil, "...mm" },
  [93225] = { "Totem intagliati dei centauri", "Ottieni $N1 Carved Centaur Totem uccidendo centauri di qualsiasi clan in tutta ⟦Desolace=Desolanda⟧, poi portali a Gurda Wildmane al ⟦Ghost Walker Post=Presidio delle Ombre⟧.", "Ho notato che i centauri di clan diversi a volte si riuniscono lontano dagli insediamenti e commerciano tra loro. L'ho osservato per molte notti e, a quanto pare, con ogni clan; soprattutto, ho visto la moneta che usano: totem intagliati.\n\nCredo che possiamo volgere le sorti a nostro favore con i Gelkis o con i Magram, se consegniamo loro direttamente un bel carico di totem. Ho già cominciato a intagliarne qualcuno, ma dubito che si lasceranno ingannare facilmente senza qualche totem autentico.", nil, nil, 0x9d52128a, 0x19fc2936, 0xb3fe9d43, nil, nil, "...mm" },
  [93226] = { "Comprare l'amicizia: Magram", "Porta il Totem Tote al quartiermastro dei Magram al Magram Village, a ⟦Desolace=Desolanda⟧, per accrescere notevolmente la tua reputazione presso quel clan. Devi essere almeno Neutrale con i ⟦Magram Clan Centaur=Centauri del Clan Magram⟧.", "Io sceglierei di schierarmi con i Magram. Non c'è dubbio che oggi siano il clan dominante, nonostante le difficoltà del passato. Ho sentito rapporti secondo cui sono brutalmente ostili verso i Gelkis.\n\nProvo simpatia per entrambi i clan in guerra, e soprattutto per i Gelkis, ma questa è la loro guerra, non la nostra. Dovremmo schierarci con la parte che comporta meno rischi per la nostra causa. Credo che siano i Magram.\n\nPorta questo al loro quartiermastro al Magram Village, a sud-est.", nil, nil, 0xf5fd14ba, 0x66df78e4, 0xe1f3c90b, nil, nil, "...mm" },
  [93227] = { "Comprare l'amicizia: Gelkis", "Porta il Totem Tote al quartiermastro dei Gelkis al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧, per accrescere notevolmente la tua reputazione presso quel clan. Devi essere almeno Neutrale con i ⟦Gelkis Clan Centaur=Centauri del Clan Gelkis⟧.", "A prima vista, scommetterei che i Gelkis sono in difficoltà. Sono molto meno numerosi dei Magram, e i nostri esploratori di rado li sentono scorrazzare in giro.\n\nCiononostante, sono uno dei clan dominanti di ⟦Desolace=Desolanda⟧ e sopravvivono ancora oggi. Qualcosa di giusto devono pur farlo.\n\nSe vuoi fare pace con i Gelkis, porta con te questa sacca di totem al ⟦Gelkis Village=Villaggio dei Gelkis⟧, molto a sud-ovest. Per quanto primitivi, avranno probabilmente una specie di tesoriere.", nil, nil, 0x57c3db29, 0x68c32afb, 0xc65c6911, nil, nil, "...mm" },
  [93317] = { "La stagione dei granchi", "Raccogli 6 pezzi di Windsong Crawler Meat.", "Conosci i Windsong Crawler? Vedi, questi granchi vivono solo nel Windsong Lake, qui su Zephras, e si possono pescare solo per poche settimane all'anno.\n\nCon tutta l'attività del culto di recente, non sono riuscito ad andare al lago a pescarli, e il tempo a disposizione sta finendo in fretta. Ti sarei grato se potessi andare a raccoglierne un po' per me. Di solito si trovano lungo le rive del lago e nei fiumi.\n\nMa sta' attent<o/a>, sono più cattivi di quanto sembrino!", "La carne di Windsong Crawler qui è abbastanza comune, ma sulle isole di Anvilas e Siroccas era una specie di prelibatezza. C'è stato un tempo, quando le correnti celesti erano aperte, in cui la gente del posto mi assaliva per averla quando facevo il viaggio fino a Shen'dramar o New Eldre'naar.\n\nNon riesco ad andare in quei posti da... be'... molto tempo.", "Che i venti mi benedicano, questa carne ha un aspetto fantastico!\n\nGrazie mille, {class}.", 0x6f40d8c7, 0x3826218b, 0xb3597e4b, 0x9e47a279, 0x2bc6df4e, "....." },
  [93318] = { "RICERCATA: Vulgara l'Insaziabile", "Uccidi Vulgara the Insatiable negli Shen'dar Highlands e porta la sua testa a Danarii Bellowveil.", "Per ordine della conestabile Aonda dei Pacificatori, si pone una taglia sul flagello degli altipiani, Vulgara l'Insaziabile. Avvistato l'ultima volta sulla cima di un'altura appena a sud-ovest di Shen'dar Village, il terrore alato dei vuldren è estremamente pericoloso e va avvicinato con cautela.\n\nConsegna la testa della bestia a Danarii Bellowveil per ricevere la ricompensa.", "Mi serve la testa della creatura come prova dell'impresa.", "Come se non avessimo già abbastanza grattacapi tra il culto e i banditi degli altipiani, ci mancava solo un vuldren gigante a terrorizzare i nostri cittadini. Oggi hai fatto una gran cosa. Come promesso, ecco la tua ricompensa.", 0x26deadde, 0x95335eb7, 0x44a54b33, 0x7e44c040, 0xedf3a0ac, "....." },
  [93319] = { "Pietre del vento rubate", "Raccogli 10 Pilfered Windstone dagli Highlands Bandit negli Shen'dar Highlands.", "Qui su Zephras ci affidiamo sempre di più alle pietre del vento per la vita di tutti i giorni, quindi cerchiamo di tenerne una scorta di riserva per le emergenze. Ultimamente ho notato che alcune spariscono dai nostri magazzini.\n\nAbbiamo trovato pietre del vento addosso ai banditi che abbiamo catturato di recente, e sospetto che dietro le nostre carenze ci siano loro.\n\nSe ti trovi vicino alla grotta dei banditi a nord, ti dispiacerebbe dare qualche bella lezione e recuperare un po' delle nostre pietre del vento rubate?", "Probabilmente questi ladruncoli saccheggiano le nostre scorte da mesi. Ho cercato di convincere Aonda a organizzare un'incursione per ripulire una volta per tutte quella grotta dei banditi, ma lei non voleva allontanare dal villaggio i pochi Pacificatori che abbiamo.\n\nCon i cultisti che crescono di numero al Falaath Village, a sud, non posso darle torto.", "Grazie, {class}. Questo dovrebbe bastarci per ora. Ma se non riusciamo a sistemare presto le vie di rifornimento, qualche pietra del vento rubata sarà l'ultimo dei nostri problemi.", 0x41d7b2ca, 0x098aea7b, 0x414845c0, 0x9132cdaf, 0x4e8fd502, "....." },
  [93320] = { "Difendere la torre", "Fai rapporto a Yorana Windyreed alla torre di guardia orientale nei Gustberry Lowlands.", "Mi è appena giunta notizia che il culto sta attaccando la torre di guardia del pilone, appena fuori dal paese! Ho mandato i pochi Pacificatori in più che abbiamo qui a cercare di sfondare le retrovie nemiche per dare sollievo ai difensori, ma ogni aiuto in più potrebbe fare la differenza tra la vita e la morte della nostra gente laggiù.\n\nTi prego, parti subito per la torre di guardia orientale e fornisci tutto l'aiuto che puoi.\n\nLa mia tenente, Yorana Windyreed, ha guidato i rinforzi. Se è ancora viva, potrà dirti come aiutare al meglio.", nil, "Per ora li stiamo tenendo a bada, ma sono più numerosi e i nostri combattenti cominciano a essere stanchi. Dobbiamo fare qualcosa per rompere lo stallo, e in fretta.", 0x0a49deab, 0x7f44b2b4, 0x98ee9961, nil, 0xbdc9cc11, "...m." },
  [93429] = { "Sangue del mio sangue", "Uccidi 10 ⟦Lost Ones=Perduti⟧ nel ⟦Fallow Sanctuary=Santuario dei Perduti⟧.", "Anche se sono nostri consanguinei, i ⟦Lost Ones=Perduti⟧ del ⟦Fallow Sanctuary=Santuario dei Perduti⟧ sono diventati creature di pura violenza e odio.\n\nPer loro non può esserci redenzione né salvezza. Sono condannati a vagare per questa palude come creature senza mente e piene d'odio per tutta la vita.\n\nLe loro sofferenze devono finire. Qualcuno deve porre fine alla loro miseria. Un compito macabro, lo so, ma lo faresti per proteggere quelli di noi che restano?", nil, nil, 0x18916a9d, 0x3b5f5f4a, 0xdbc3d8f8, nil, nil, "...mm" },
  [93430] = { "Riprendersi l'esca", "Trova il Lost One Fisherman che ha rubato l'esca di Pelluk e riprendila.", "Stavolta l'hanno fatta grossa! Come se quei disgraziati non fossero già abbastanza un problema, uno di loro mi ha rubato l'esca portafortuna!\n\nStamattina ero fuori a pescare, quando uno è sbucato dal fango, mi ha tagliato la lenza ed è scappato con l'esca. Il ladro è quasi di certo uno dei pescatori dei ⟦Lost Ones=Perduti⟧, che spera di usare l'esca per sé.\n\nBe', le nostre scorte di pesce dipendono da quell'esca, quindi la rivoglio. I ⟦Lost Ones=Perduti⟧ pescano lungo le rive a est di qui. Trova quel ladro, {race}!", nil, nil, 0x42cf1db9, 0xb7ae8a79, 0x115f80e5, nil, nil, "...mm" },
  [93459] = { "Altre orecchie di Al'Aketh", "Raccogli 10 Al'Aketh Cultist's Ear dagli Al'Aketh nella Shadowgale Forest, allo Shrine of Akir o nei Gustberry Lowlands e portale a Vayn Moonclaw nella Shadowgale Forest.", "Il culto degli Al'Aketh di solito si tiene alla larga da questa foresta, temendo le voci che sia infestata... voci che siamo ben felici di alimentare. I druidi del mio ordine desiderano solo vivere una vita quieta e pacifica qui a Shadowgale, e loro la minacciano.\n\nMolti di noi hanno paura.\n\nVengo con un'offerta. Combatti i cultisti per noi e portaci le orecchie di quelli che uccidi. Ti ricompenseremo per ognuna che ci porterai, con denaro e, col tempo, con l'accesso ai nostri segreti, se dimostrerai di essere un vero amico.", "<Vayn ti fa un cenno con il capo.>", "Come promesso, ecco la tua ricompensa.", 0x91339b63, 0x4cc2e33c, 0x184326a2, 0xe91596f9, 0x53f5cf99, "....." },
  [93461] = { "Benvenuti a Shen'dar Village", "Parla con Rathiril Sunlance e Coriella Calmbreeze a Shen'dar Village.", "Hai proprio l'aria da \"High Order\". Chi ha antenati ⟦Highborne=Alti Nobili⟧ sembra sempre avere un lieve scintillio negli occhi che lo tradisce. Prima che ti metta al lavoro come si deve, dovresti presentarti al nostro anziano dell'High Order, Rathiril Sunlance. Lo trovi qui nella loggia principale, appena dietro l'angolo.\n\nAh, e passa anche da Coriella Calmbreeze: gestisce la locanda del posto e può darti alloggio e provviste, se ti servono.", nil, "Allora ti sei presentat<o/a> a Rathiril? Ottimo. C'è parecchia tensione tra l'High Order e i Windshaper di questi tempi, ma qui a Shen'dar mantengono i rapporti civili. Be', almeno nel villaggio. Quello che succede nelle terre selvagge resta nelle terre selvagge.\n\nOra che è fatta, hai l'aria di chi cerca qualcosa da fare con le proprie mani. Ho alcune cose da sbrigare, se te la senti di lavorare un po'.", 0x4c9d3c02, 0xe867665b, 0x8517821c, nil, 0xbc58bc08, "...m." },
  [93464] = { "Il mago in visita", "Trova il mago di ⟦Desolace=Desolanda⟧ che conosce il potere del draenetista.", "Lascia che ti confessi una cosa, {name}. Anche se il draenetista è sacro per noi e ci mantiene sani di mente, nessuno qui lo comprende davvero.\n\nRicordo un mago che una volta venne al Rifugio dei Corrotti da ⟦Desolace=Desolanda⟧. Un umano di nome Azore. Temeva il potere del draenetista; diceva che non doveva finire nelle mani sbagliate.\n\nAll'epoca lo cacciammo per proteggere ciò che era nostro. Ultimamente, però, mi ritrovo a chiedermi cosa sapesse esattamente.\n\nTi chiedo di trovare questo mago, {race}. Le sue conoscenze potrebbero esserci di immenso valore.", nil, nil, 0x8dd4d8e6, 0x5dd0e284, 0x339bbfeb, nil, nil, "...mm" },
  [93465] = { "Appunti sul draenetista", "Prendi gli appunti di Gimashi sul draenetista e portali ad Azore Aldamort.", "Forse sarebbe più esatto dire che conosco qualcuno che ne sa qualcosa sul draenetista.\n\nVedi, gli stregoni delle ⟦Burning Blade=Lame Ardenti⟧ lo stanno studiando. È una sostanza che viene da oltre il Portale Oscuro, quindi è logico che chi pratica le arti più oscure voglia piegarla ai propri scopi. Non possiamo permetterlo, ovviamente.\n\nLa stregona che cerchi si chiama Gimashi. La trovi in cima alla sua torre, in un burrone a sud-est. I suoi appunti avranno le risposte che cerchi.", nil, nil, 0x187f109c, 0xbf8231d0, 0x92cd47bd, nil, nil, "...mm" },
  [93552] = { "Raccolta di pietre del vento", "Raccogli 15 Windstone Cluster dalle Raw Windstone a Thendal Grove.", "Le pietre del vento sono una risorsa vitale sull'isola di Zephras, perché racchiudono l'energia pura e concentrata dei venti stessi. Gli elementali del vento che un tempo vivevano qui a Zephras insieme a noi sono scomparsi parecchi anni fa e, da allora, la magia che sostiene quest'isola si sta lentamente affievolendo. Pur con i loro limiti, le pietre del vento restano una fonte di energia affidabile e per noi hanno un valore immenso.\n\nTroverai pietre del vento grezze sparse per il boschetto. Pensi di potermi aiutare a raccoglierle?", "Salve, {class}.", "Grazie mille per queste. Come elfi, abbiamo tutti un legame profondo con la magia, e queste pietre del vento diventano sempre più preziose mano a mano che la magia infusa in quest'isola dai grandi piloni d'ancoraggio continua ad affievolirsi.\n\nLe pietre del vento non sono l'unica cosa utile che puoi raccogliere da questa terra. Ti prego, prendi uno di questi manuali.", 0x2bcfca6e, 0xe8cd67c8, 0x3a9bfe02, 0x1c31b804, 0x7fc437ff, "....." },
  [93585] = { "Questa mia luce", "Scorta padre Tuttle fino al ⟦The Harborage=Rifugio dei Corrotti⟧.", "Oh, grazie al cielo, qualcuno di civile!\n\nSono venuto qui per conto della Chiesa della ⟦Holy Light=Luce Sacra⟧, per stabilire un contatto con i draenei del Rifugio dei Corrotti. Vedi, l'⟦Alliance=Alleanza⟧ non ha alcun punto d'appoggio da queste parti, e un po' di diplomazia con la gente del posto potrebbe aiutarci in questo senso. Dopotutto, la Luce accoglie tutti nel suo abbraccio!\n\nPerò la strada oltre questo ponte brulica dei parenti più selvaggi dei draenei. Se devo arrivare sano e salvo al Rifugio dei Corrotti, mi serve una scorta. Mi aiuterai, {class}?", nil, nil, 0xc51f3c34, 0x6d345a6d, 0xd75f821d, nil, nil, "...mm" },
  [93663] = { "Smarrito in viaggio", "Trova il corriere scomparso e assicurati che il carico di Dar venga consegnato al Rifugio dei Corrotti.", "I draenei del Rifugio dei Corrotti sono pescatori abili e disposti a gettare le reti in acque più pericolose di quanto farei io. Ogni tanto commerciamo: loro ci danno parte del loro pescato e io offro un po' delle nostre provviste in eccesso.\n\nAvevo mandato un corriere goblin a consegnare il mio ultimo carico, ma non è mai tornato. Probabilmente se l'è mangiato un crocolisco.\n\nMa c'è di peggio: è in gioco la mia reputazione negli affari. Quel carico va ritrovato e consegnato al Rifugio dei Corrotti. Ti prego, trovalo, se ci riesci. Cerca vicino all'acqua, lungo la strada.", nil, nil, 0x6d5f7446, 0x57be44a4, 0xbeef4b7a, nil, nil, "...mm" },
  [93680] = { "La chiave della città", "Procurati la Dalaran Sewer Key per il magus Wordeen Voidglare al ⟦Tarren Mill=Mulino di Tarren⟧.", "L'⟦Alliance=Alleanza⟧ aveva un esercito di maghi chiamato Kirin Tor. Per quanto fossero potenti, la demoniaca Legione Infuocata si dimostrò ancora più forte. In un colpo solo l'arcidemone Archimonde rase al suolo la loro città come fosse il giocattolo di un bambino. I superstiti furono ridotti a semplici vagabondi senza dimora.\n\nAlmeno finché non ricostruirono Dalaran. E per giunta proprio alle porte della Dama Oscura!\n\nMentre sei nei loro accampamenti, cerca qualcosa che ci permetta di entrare in città senza essere notati. Devo saperne di più.", nil, nil, 0xc31a2dd3, 0xa0350c6f, 0xab6858c6, nil, nil, "...mm" },
  [93689] = { "Amico del Kirin Tor", "Parla con l'arcimaga Celindra nella città di Dalaran.", "Questa è una notizia eccellente! Ora che a Dalaran è tornata la pace, non vedo perché il Kirin Tor non dovrebbe accoglierti a braccia aperte!\n\nTi prego, presentati al consiglio al più presto. Sono certo che non vedranno l'ora di conoscere <il/la> <salvatore/salvatrice> della città.", nil, nil, 0xa01b2371, 0x8dfa9ac1, 0x71e69736, nil, nil, "...mm" },
  [93735] = { "Il costrutto guasto", "Trova Riaani Nightwind sul lato occidentale di Valanaar.", "Da sempre i Windshaper si occupano della cura degli strumenti e dei congegni magici che ci furono donati dagli spiriti del vento, tra cui la miriade di costrutti magici sparsi per l'isola. Da quando gli spiriti ci hanno lasciati, solo pochissimi di questi funzionano ancora.\n\nUno dei pochi costrutti ancora funzionanti di Valanaar si è danneggiato. Abbiamo mandato uno dei nostri artigiani a ripararlo, ma potrebbe aver bisogno di aiuto. Recati all'estremità occidentale della città e offrigli tutta l'assistenza che puoi.", nil, "<Riaani ha la faccia sepolta sotto le pesanti piastre corazzate del costrutto e cerca di lavorare ai meccanismi sottostanti. Non si accorge minimamente della tua presenza.>\n\nChe le tempeste lo maledicano, dov'è il nucleo?! A chi è venuto in mente di rimuovere anche il Gyrozephyr? È un miracolo che i venti di questo costrutto non si siano ancora dissolti del tutto!", 0x3b580ff6, 0xb230d6e2, 0x9c9b9f2d, nil, 0x121d9405, "...m." },
  [93736] = { "Spiriti indesiderati", "Raccogli 10 Wind Hollow Essence dai Wind Hollow nella Shadowgale Forest.", "La preoccupazione principale dei Windshaper è capire meglio perché gli spiriti ci abbiano lasciati, e cosa potremmo fare per riportarli indietro. Una curiosa presenza nella Shadowgale Forest, a nord, è quella di una strana forma di spiritello del vento che alcuni chiamano «hollows». Sappiamo poco di loro e del perché si trovino lì, ma sappiamo che hanno cominciato a comparire dopo che gli spiriti del vento ci hanno lasciati.\n\nHo bisogno che tu vada laggiù a disperderli. Raccogli i loro resti e portali qui.", "La Shadowgale Forest è un luogo pericoloso. Alcuni dicono perfino che sia infestata. Io non ci credo affatto, ma so bene che non è un posto per i deboli di cuore, né per chi è impreparato.", "Maneggiare queste essenze mi riempie di un senso di... profonda inquietudine. Riesco quasi a percepire un'aura maligna e piena di rimpianto che emana da esse. C'è da sentirsi mancare.\n\n<Endaria rabbrividisce leggermente.>\n\nNon ho alcuna voglia di studiarle ancora.", 0x4f4a02b2, 0x24071ed5, 0x120ac132, 0x720c2c52, 0x64b49c6f, "....." },
  [93737] = { "Il costrutto guasto", "Parla con Riaani Nightwind e ascolta ciò che ha da dire.", "Oh, salve. Ti ha mandato Ayessa ad aiutarmi? E va bene.\n\nNon so cosa possa fare <un/una> principiante come te, ma se mi dai un momento per tirare fuori la testa dalle viscere di questo costrutto, forse mi verrà in mente qualcosa con cui puoi renderti utile.", "Non riesco proprio a immaginare perché qualcuno voglia rubare questi componenti a questo costrutto. A parte il gyrozephyr, non hanno quasi nessuna utilità pratica. E perfino il gyro sarebbe pressoché inutile fuori dallo scopo per cui è stato creato.", "Grazie per aver recuperato questi materiali. Immagino che procurarsene alcuni non sia stato per niente facile.\n\nCon questi pezzi posso rimettere in funzione il costrutto. Da lì in poi possiamo solo sperare che la sua memoria sia intatta e che possa dirci chi ha preso i suoi componenti.", 0x3b580ff6, 0x20bf5d1d, 0xc9fcddd9, 0x57705db0, 0xf88bb130, "....." },
  [93738] = { "Il costrutto guasto", "Torna a fare rapporto ad Ayessa Dawnsinger a Valanaar.", "Brightwish, eh? Quindi l'High Order voleva rimuovere questi componenti per qualche motivo. Ma perché?\n\nL'High Order è sempre stato invadente, sempre ansioso di sperimentare con la magia degli spiriti del vento. Sono fin troppo sfrontati, e abbiamo proibito loro severamente di immischiarsi nelle conoscenze di competenza dei Windshaper, ma ultimamente stanno mettendo alla prova la nostra pazienza.\n\nPenso che dovresti riferire ciò che hai scoperto ad Ayessa Dawnsinger. Lei saprà dirti cosa fare.", nil, "Molto interessante. Quindi è stato l'High Order a far guastare il costrutto?\n\nConosco Belathaan. È il cugino di Valennia Stormfist, e sua madre era una Windshaper. È deludente che sia coinvolto in questa faccenda.\n\nHo bisogno di riflettere un momento.", 0x3b580ff6, 0x29d7b548, 0x98b46a4e, nil, 0xe4724d1e, "...m." },
  [93739] = { "Alla scoperta dell'⟦Horde=Orda⟧", "Parla con Nazgrel a Grommash Hold per ricevere altre istruzioni. Segui le istruzioni ricevute per trovare Vol'jin, Cairne Bloodhoof e Lady Sylvanas Windrunner e parlare con loro.", "Azeroth è un mondo vasto, e il territorio dell'⟦Horde=Orda⟧ è immenso. ⟦Undercity=Sepulcra⟧, Orgrimmar e ⟦Thunder Bluff=Picco del Tuono⟧ hanno popoli e culture davvero unici.\n\nSe devi essere ospite dell'⟦Horde=Orda⟧ qui su Azeroth, ti farebbe bene visitare una dopo l'altra tutte le nostre capitali. Parla con il mio consigliere Nazgrel per avere indicazioni.", nil, "Dunque sei <tornato/tornata>. Spero che tu abbia imparato molto durante il viaggio.\n\nA quanto mi risulta, la tua gente si sta ancora stabilendo a Mulgore. Mentre li aspetti, ti consiglio di esplorare il territorio intorno a Orgrimmar. Le ⟦The Barrens=Savane⟧, in particolare, hanno sempre bisogno di avventurieri volenterosi come te.", 0x7968676a, 0x9721d08e, 0xc1326b85, nil, 0x9b3fc549, "...m." },
  [93740] = { "Sangue per sangue", "Raccogli 10 Al'Aketh Windstone Charm dai cadaveri dei cultisti Al'Aketh nei Gustberry Lowlands.", "Stamattina alcuni dei nostri novizi Windshaper sono stati trovati morti negli altopiani. Non possiamo esserne certi, ma con ogni probabilità i responsabili sono gli Al'Aketh. I Windshaper ripagano sangue con sangue, ogni volta.\n\nDirigiti a nord e uccidi tutti gli Al'Aketh che incontri. Portami i loro amuleti di preghiera di pietra del vento come prova dell'opera compiuta. Noi non perdoniamo e non dimentichiamo.", "Gli Al'Aketh si abbandonano al loro fanatismo sanguinario da fin troppo tempo. Questo è solo l'inizio della resa dei conti che li attende.", "<Ayessa sembra scossa e assente mentre le consegni gli amuleti di pietra del vento.>\n\nNon badare a me, {name}. Oggi è stata solo... una giornata difficile. Grazie per ciò che hai fatto finora per i Windshaper.", 0x8fdc4a0a, 0xc45880fd, 0xe1adb7e7, 0xe653122a, 0x7adc4448, "....." },
  [93746] = { "Una risposta ferma", "Affronta Belathaan Brightwish lungo la strada per lo Shrine of Akir.", "L'High Order è stato avvertito delle conseguenze dell'immischiarsi negli affari dei Windshaper. Credo che dobbiamo dare l'esempio con Belathaan e rimandarlo all'High Order con qualche livido e un sano rispetto per i limiti che abbiamo fissato.\n\nBelathaan è stato visto lasciare la città, diretto a nord verso lo Shrine of Akir. Non so perché stesse andando laggiù, ma affrontarlo da solo sulla strada è la scelta più sicura. Trovalo e mettigli un po' di paura in corpo.", nil, "Aspetta... cosa?! Belathaan... è morto?\n\n<Ayessa ascolta il tuo racconto dell'accaduto.>\n\nL'High Order si incontrava con gli Al'Aketh per discutere di pace? Non c'è pace possibile con il culto, sono fanatici assassini. Cosa pensava Elaadrin, mandando Belathaan da solo a trattare con loro?\n\nNon pensarci più, {name}. Non è colpa tua. La colpa è dell'arroganza dell'High Order, ancora una volta. Ti sei solo <trovato/trovata> nel posto giusto al momento sbagliato.", 0x2e10a415, 0x87bb368c, 0x049e9393, nil, 0x348cc12c, "...m." },
  [93791] = { "Parlare con Belann", "Parla con Belann Windwood a Valanaar.", "{name}, è chiaro che la tua abilità con la magia sta crescendo, e credo sia giunto il momento che tu prenda parte a una delle tradizioni più antiche dell'High Order per i maghi giovani e promettenti. È ora che tu crei un tuo focus degli incantesimi.\n\nCerca Belann Windwood a Valanaar. Fabbrica bastoni e bacchette per l'High Order da più di un secolo, quindi sarai in buone mani.", nil, "Ah, tu devi essere {name}, giusto? È confortante vedere giovani maghi desiderosi di imparare le nostre usanze e la nostra storia. Vieni, ti spiegherò i prossimi passi per creare il tuo focus degli incantesimi.", 0x9eee1307, 0xdac9b99f, 0x9e12128a, nil, 0x293bd11b, "...m." },
  [93797] = { "Rami nel vento", "Porta un Wind-Infused Bough a Belann Windwood a Valanaar.", "È una tradizione consolidata che i giovani maghi creino il proprio focus degli incantesimi quando hanno dimostrato un certo grado di abilità magica. Di solito si comincia raccogliendo un ramo caduto dai nostri alberi più antichi, perché conservano ancora tracce del vento elementale.\n\nI più adatti li ho trovati vicino al santuario del vento, appena a sud di Falaath Village. Va' e portami un grosso ramo: ti insegnerò le tradizioni mentre creiamo il tuo focus degli incantesimi.", "Ogni anno che passa, a Zephras nascono sempre meno persone dotate di talento per la magia.\n\nSono lieto di vedere giovani maghi come te prendere parte alle nostre tradizioni più antiche, per mantenere viva la nostra storia e la nostra cultura.", "Grazie, {name}. Sento davvero le energie elementali in questo ramo, in attesa di essere imbrigliate da chi ha il dono per farlo. Ne verrà fuori un eccellente focus degli incantesimi.\n\nQuesto ramo ti ha forse cantato? Capita spesso che sia il ramo a scegliere <il/la> {class}, e non il contrario.\n\n<Belann ridacchia mentre ti prende delicatamente il ramo.>", 0x53b7cabb, 0xbb3c4f26, 0x55b3e7d7, 0xf0384662, 0x12ab22f5, "....." },
  [93835] = { "Affrontare Lorthuna", "Prendi il portale verso le Rohashi Spires, qui sopra, e unisciti a Elaadrin Evengale e Ayessa Dawnsinger nello scontro con la somma sacerdotessa Lorthuna.", "Lorthuna è fuggita sulle guglie qui sopra attraverso una specie di portale. Ayessa ed Elaadrin le sono andati dietro. È successo solo pochi istanti fa.\n\nTemo di aver preso un colpo di troppo: per me il viaggio finisce qui. Attraversa il portale, trova Elaadrin e aiutali a fermare Lorthuna.\n\nA meno che non arrivino presto i rinforzi che Elaadrin e Ayessa dicono di aver chiesto, da qui in poi dovrai cavartela da te. Buona fortuna, {class}.", nil, "Ho mandato alcuni dei maghi che ci restano ad assicurarsi che anche Valennia e le sue forze riuscissero a fuggire. A quest'ora dovrebbe riposare nella residenza dell'anziano supremo Shadowsong.\n\nAnsirem è dovuto tornare su Azeroth, ma prima di partire abbiamo discusso insieme delle prossime mosse dell'High Order. Siamo sopravvissuti a questa giornata, ma ora Zephras è pericolosamente vulnerabile e dobbiamo prepararci a ciò che verrà.", 0x90290d9d, 0x21f66bcc, 0xcf4192f2, nil, 0x2047cb19, "...m." },
  [93836] = { "Il destino di Zephras", "Parla con Talaanis Shadowsong a Valanaar.", "Muln mi ha raccontato molto dei signori elementali, e temo che abbiamo buone ragioni per temere Al'Akir. Ora che le protezioni che nascondevano Zephras al suo sguardo sono cadute, siamo del tutto indifesi. Se decidesse di attaccarci, non avremmo alcuna possibilità contro di lui, qui nel suo stesso dominio.\n\nL'anziano supremo Shadowsong deve sapere in che pericolo ci troviamo e, soprattutto, quali sono le nostre intenzioni per la nostra missione su Azeroth. Troveremo il modo di salvare la nostra casa. Lo giuro.", nil, "<Talaanis Shadowsong ascolta con attenzione mentre gli racconti ciò che è accaduto sopra lo Shrine of Akir e il piano di Ayessa di lasciare l'isola di Zephras.>\n\nDevo rifletterci ancora, ma guardando il lato positivo, ci siamo liberati di Lorthuna e abbiamo privato il culto della sua guida. La nostra casa non è ancora stata invasa e, sulla scala del tempo degli dei elementali, potrebbero passare anni... perfino decenni, prima che Al'Akir si degni di rivolgere la sua attenzione a noi.\n\nOra c'è molto da temere, ma anche molto da festeggiare.", 0x6d3ea2fe, 0x4440ff8a, 0x7c6d6603, nil, 0xa70add28, "...m." },
  [93862] = { "Restituzione della cassa", nil, nil, nil, nil, 0xeb410c2b, nil, nil, nil, nil, ".mmmm" },
  [93926] = { "La vedetta occidentale", "Trova il custode della pace Vaaniel alla torre di guardia occidentale.", "Qualunque sia il motivo per cui il culto attacca la torre, non vale la vita della nostra gente.\n\nVorrei che andassi a sud-ovest a controllare quella torre di guardia per noi. Trova i custodi della pace che sono lì e di' loro di tornare al villaggio. Tenere quella torre non vale le vite che costerebbe, e preferisco concentrare qui i difensori che abbiamo per proteggere i nostri cittadini.\n\nIl comando è del custode della pace Vaaniel: digli di tornare qui il prima possibile. Sbrigati!", nil, "<Il corpo è piuttosto fresco: è evidente che è stato ucciso da poco. A giudicare dalle ustioni e dai segni di bruciatura sulla pelle di questo custode della pace, è chiaro che è stato ucciso dagli incantatori del culto che comandano le tempeste.>", 0x18869d4a, 0xc19f2264, 0x3e46d2b0, nil, 0x1742715f, "...m." },
  [93927] = { "Un'ultima richiesta", "Raccogli il biglietto che hai trovato vicino al custode della pace morto e leggilo per capire come procedere.", "<Mentre esamini il corpo del custode della pace morto, un biglietto insanguinato gli scivola dalle mani. Raccoglierlo e leggerlo potrebbe darti un indizio su come procedere.>", "Che notizie porti dalla vedetta occidentale?", "Dunque sono tutti morti. Che le tempeste maledicano quei bastardi del culto!\n\nSei riuscit<o/a> a eliminare il sacerdote e a fermare i cultisti alla torre, ma confesso che ora sono doppiamente preoccupato per ciò che, a quanto dici, stavano facendo al pilone. Il fatto che avessero con sé una scorta così enorme di pietre del vento mi dice che avevano bisogno di un'energia immensa.\n\nMi chiedo quale sia il loro vero scopo. Profanare il pilone, attaccare il villaggio? A che fine?", 0x96fa8046, 0xf1e8b9e6, 0xc18d4d9f, 0x3a64b789, 0xad2ad512, "....." },
  [93928] = { "Di topi e latte", "Procura un biscotto al topo.", "Mi serve un biscotto, capito?\n\nNyeah!", nil, nil, 0x4a4cc954, 0xaadb1f71, 0xe2b329a9, nil, nil, "...mm" },
  [93948] = { "La consegna del sigillo", "Consegna lo Shadowsong Family Signet a Talaanis Shadowsong a Valanaar.", "Visto che vai comunque a Valanaar, ti prego, porta l'anello con sigillo che hai recuperato dalla torre a Talaanis Shadowsong, a Valanaar.\n\nVorrà riaverlo e, soprattutto, vorrà conoscere la sorte di suo nipote. Talaanis è l'anziano supremo dell'isola di Zephras e, cosa ancora più importante, è un brav'uomo molto amato dal popolo, nonostante le difficoltà di questi tempi. Mi addolora pensare a come reagirà a questa notizia. Ti prego, porgigli le mie condoglianze per la sua perdita.", "Che cosa hai da darmi? Oh... oh, no.", "Io... sono molto addolorato di sapere che mio nipote è morto. Ti ringrazio di cuore per aver recuperato questo anello e per avermelo portato.\n\nNon capita spesso che shen'dorei giovani e capaci come te scendano dagli altopiani. Se cerchi lavoro, parla con Valennia Stormfist, il capitano dei custodi della pace qui a Valanaar. Di questi tempi ci serve tutto l'aiuto possibile.", 0x95398690, 0x57f7b4b1, 0xba89a78d, 0x93229de8, 0x0454cabb, "....." },
  [93949] = { "Intercettati", "Uccidi gli Skyhopper a Valanaar finché non avrai eliminato $N1 Enchanted Skyhopper.", "Ci stanno spiando.\n\nNelle pianure è la stagione degli skyhopper, il che significa che quegli insetti molesti sono dappertutto. Uno dei maghi dell'High Order ha riferito che uno degli insetti uccisi portava addosso un qualche incantamento. Esaminandolo da vicino, sembra una specie di incantesimo d'ascolto.\n\nSospettiamo che il culto usi questi insetti incantati come spie. Va' a sterminarli per noi. Non potrai capire quali sono incantati solo guardandoli, quindi dovrai ucciderli tutti.", nil, "Di sicuro ci sono altre di queste bestiole intorno a Valanaar, ma ogni skyhopper incantato che schiacciamo rende la città un pochino più sicura.", 0xebc83872, 0xf0db79e8, 0x5a7063fe, nil, 0xf7ae869a, "...m." },
  [93951] = { "Un tocco di bellezza", "Raccogli 8 piume di Hippogryph Down negli Shen'dar Highlands.", "Gli ippogrifi che si sono stabiliti a sud-ovest del villaggio possono essere una seccatura, ma offrono anche un'occasione piuttosto unica per procurarsi le loro piume. Molti skyborne adorano ornarsi i capelli con piume vivaci, e il piumino di un ippogrifo è straordinariamente vivace e, soprattutto, morbido come la seta.\n\nSe vai da quelle parti, cerca di raccogliere quante più piume cadute puoi intorno ai loro nidi. Ma fa' attenzione: gli ippogrifi selvatici non tollerano gli ospiti.", "Quali cose meravigliose mi hai portato?", "Raccogliere piume per i capelli potrebbe sembrare una frivolezza un po' vanitosa. Eppure, anche in tempi come questi, bisogna abbracciare il più possibile le piccole gioie.\n\nSe una sola cosa che creo porta gioia a qualcuno, per me è una buona giornata. Grazie per avermele portate e per avermi aiutato a portare un po' di gioia a Zephras.", 0xfb24871b, 0xf83626f8, 0x2b37a842, 0x1bd026f8, 0x6c68b48e, "....." },
  [93958] = { "Il santuario interno", "Parla con Valennia Stormfist nel santuario interno dello Shrine of Akir.", "Le forze di Valennia hanno appena fatto breccia nel santuario interno. All'inizio là dentro si combatteva duramente, ma ora è calato un silenzio... inquietante. Entra e fa' del tuo meglio per ricongiungerti con Valennia e le sue forze... se ne è rimasto qualcuno.\n\nIo resto qui a guardarti le spalle.", nil, "<Valennia sembra gravemente ferita.>", 0x757fc20c, 0xb9c9ad7e, 0xfe6de4be, nil, 0x3a2cf55d, "...m." },
  [93963] = { "Alla scoperta dell'⟦Alliance=Alleanza⟧", "Parla con Randal Emerson nel Castello di ⟦Stormwind=Roccavento⟧ per ricevere altre istruzioni. Segui le istruzioni ricevute per trovare re Magni Bronzebeard, l'alto inventore Mekkatorque e Tyrande Whisperwind e parlare con loro.", "⟦Stormwind=Roccavento⟧, ⟦Ironforge=Forgiardente⟧ e Darnassus hanno tutte popoli e culture unici. Come ospite dell'⟦Alliance=Alleanza⟧ qui su Azeroth, dovresti prenderti un po' di tempo per visitare una dopo l'altra tutte le nostre capitali.\n\nParla con Randal Emerson nell'anticamera meridionale: ti darà le indicazioni per cominciare.", nil, "Ah, sei <tornato/tornata>.\n\nSpero che le tue avventure ti abbiano dato un'idea della grandezza e delle meraviglie del nostro mondo. So che deve sembrarti travolgente, ma se vuoi aiutare la tua gente, devi essere <pronto/pronta> a tutto ciò che potrebbe capitarti mentre sei su Azeroth.\n\nMentre aspetti che il tuo ordine si stabilisca a Dalaran, ti suggerisco di rivolgere la tua attenzione alle terre intorno a ⟦Stormwind=Roccavento⟧. Le ⟦Westfall=Marche Occidentali⟧, in particolare, hanno sempre bisogno di altri avventurieri forti che le aiutino, se sei <disposto/disposta> a farlo.", 0xb5c2bf15, 0x80cbe7b7, 0x7db457d1, nil, 0xd5e8b7c2, "...m." },
})
